package main

import (
	"encoding/json"
	"log"
	"net/http"
)

type Report struct {
	Service string `json:"service"`
	count   int    `json:"count"`
}

type Store struct {
	total int
	seen  map[string]int
}

func (s Store) Touch(name string) {
	s.total++
	s.seen[name]++
}

var store Store

func handle(w http.ResponseWriter, r *http.Request) {
	var rep Report
	if err := json.NewDecoder(r.Body).Decode(&rep); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	store.Touch(rep.Service)
	json.NewEncoder(w).Encode(rep)
}

func main() {
	http.HandleFunc("/report", handle)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

type Report struct {
	Service string `json:"service"`
	Count   int    `json:"count"`
}

type Store struct {
	mu    sync.Mutex
	total int
	seen  map[string]int
}

func (s *Store) Touch(name string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.total++
	s.seen[name]++
}

var store = Store{seen: make(map[string]int)}
